const esbuild = require('esbuild');
const fs = require('fs');
const path = require('path');

/**
 * Bundles the query language parser for the data composition schema page
 * (src/templateEditor/dcsQueryCore.ts) into
 * resources/preview-core/host/query-core.js as the BslQueryBuilderCore global.
 */
function bundleDcsQueryCore() {
  const rootDir = path.resolve(__dirname, '..');
  const entryPoint = path.join(rootDir, 'src', 'templateEditor', 'dcsQueryCore.ts');
  const outFile = path.join(rootDir, 'resources', 'preview-core', 'host', 'query-core.js');
  const result = esbuild.buildSync({
    entryPoints: [entryPoint],
    bundle: true,
    platform: 'browser',
    format: 'iife',
    globalName: 'BslQueryBuilderCore',
    target: 'es2020',
    charset: 'utf8',
    write: false,
  });
  const header =
    '/* Generated by scripts/bundle-dcs-query-core.js from src/templateEditor/dcsQueryCore.ts; do not edit. */\n';
  const next = header + result.outputFiles[0].text;
  const current = fs.existsSync(outFile) ? fs.readFileSync(outFile, 'utf8') : '';
  if (current !== next) {
    fs.writeFileSync(outFile, next, 'utf8');
    console.log('[bundle-dcs-query-core] Updated resources/preview-core/host/query-core.js.');
  }
}

if (require.main === module) {
  bundleDcsQueryCore();
}

module.exports = { bundleDcsQueryCore };
